text:
{
  "title_novice": "Короткая жизнь рукава — узкие песчаники",
  "summary": [
    {"text": "Дельтовые рукава существуют недолго по сравнению с речными руслами. Поэтому их песчаные тела часто вытянуты: ширина мала относительно длины.", "claims": ["c1", "c2", "c3"]},
    {"text": "Низкое отношение ширины к длине — признак формы песчаного тела, который связан с короткой жизнью рукава.", "claims": ["c2"]}
  ],
  "claims": [
    {"key": "c1", "text": "Неустойчивость дельтовых рукавов определяет, что они живут недолго.", "kind": "inference", "unit_id": "u-039-dd576c", "page": 39, "quote": "Неустойчивый характер дельтовых рукавов определяет небольшую длительность их существования по сравнению с речными руслами.", "numbers": [], "question": null},
    {"key": "c2", "text": "Песчаные тела в дельтовых рукавах часто имеют низкое отношение ширины к длине.", "kind": "inference", "unit_id": "u-039-dd576c", "page": 39, "quote": "Поэтому песчаные тела в них часто отличаются низким отношением ширины к длине.", "numbers": [], "question": null},
    {"key": "c3", "text": "Срок жизни дельтового рукава сравнивается с сроком жизни речного русла: первый короче.", "kind": "observation", "unit_id": "u-039-dd576c", "page": 39, "quote": "небольшую длительность их существования по сравнению с речными руслами", "numbers": [], "question": null},
    {"key": "c4", "text": "Перехват рукавов (авульсия) — обычное явление, которое ведёт к их отмиранию.", "kind": "observation", "unit_id": "u-037-9107ce", "page": 37, "quote": "Обычным явлением бывает перехват (авульсия [avulsion]) рукавов, ведущий к их отмиранию", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Неустойчивость дельтовых рукавов сокращает время их существования по сравнению с речными руслами.", "claims": ["c1", "c3"], "hypothesis": false},
    {"text": "Автор связывает причину и следствие словом «поэтому»: короткая жизнь рукава — затем форма песчаного тела.", "claims": ["c1", "c2"], "hypothesis": false},
    {"text": "Низкое отношение ширины к длине означает, что тело узкое относительно своей длины.", "claims": ["c2"], "hypothesis": false},
    {"text": "Физически рукав, который живёт мало, может не успеть расшириться и сместиться вбок, поэтому тело остаётся узким относительно длины.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Специалист, видя узкое вытянутое песчаное тело, может считать рукав недолговечным.", "claims": [], "hypothesis": true},
    {"text": "Вывод делают с оговоркой: автор пишет «часто», а не «всегда», поэтому не каждое тело такое.", "claims": ["c2"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Автор пишет «часто»: низкое отношение встречается не во всех песчаных телах рукавов.", "claims": ["c2"], "hypothesis": false},
    {"text": "Сравнение идёт с речными руслами, а не с абсолютным сроком жизни в годах.", "claims": ["c3"], "hypothesis": false},
    {"text": "В тексте нет числовых порогов: ни для «низкого» отношения, ни для «небольшой» длительности.", "claims": [], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Перехват рукава и его отмирание", "text": "Автор называет перехват рукавов обычным явлением, которое ведёт к их отмиранию. Это ещё одна причина короткой жизни рукава.", "claims": ["c4"], "hypothesis": false}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Числовых порогов в единице нет. Условия: рукав живёт меньше речного русла, и тела «часто» имеют низкое отношение ширины к длине.", "claims": ["c1", "c2"]}
  ],
  "terms_defined": [
    {"term": "отношение ширины к длине песчаного тела", "term_en": "width-to-length ratio of a sand body", "abbr": "", "definition": "Отношение ширины песчаного тела к его длине. Низкое значение означает, что тело узкое относительно длины.", "claims": ["c2"]},
    {"term": "речное русло", "term_en": "river channel", "abbr": "", "definition": "Углубление, по которому течёт река. В тексте сравнивается с дельтовым рукавом по сроку жизни.", "claims": ["c3"]}
  ],
  "terms_used": ["дельтовый рукав", "песчаное тело", "длительность существования", "неустойчивый характер", "ширина", "длина"],
  "formulas": [],
